std::vector<int> data = {5, 1, 9, 3, 7};

// Vector: Cache-friendly O(1) access
int third = data[2];

// Sorting O(N log N)
std::sort(data.begin(), data.end());
// data is now {1, 3, 5, 7, 9}

// O(N) accumulation
long sum = std::accumulate(data.begin(), data.end(), 0L);
// sum is 25

// Fill with value 42
std::fill(data.begin(), data.end(), 42);

std::vector<int> nums = {1, 2, 3, 4, 5};
std::vector<int> squared;

// Use back_inserter for dynamic destination resizing
// Transform: Apply lambda function O(N)
std::transform(nums.begin(), nums.end(),
               std::back_inserter(squared),
               [](int n) { return n * n; });

// Find: Stop at first element meeting criteria
auto it = std::find_if(squared.begin(), squared.end(),
                       [](int n) { return n > 10; });
// *it is 16 (or end() if not found)

std::vector<int> raw = {4, 1, 4, 2, 1, 3, 2};

// Use std::set for guaranteed uniqueness (O(N log N))
std::set<int> unique_elements(raw.begin(), raw.end());
// unique_elements: {1, 2, 3, 4}

// Idiomatic uniqueness using algorithms:
std::sort(raw.begin(), raw.end()); // O(N log N)
// Move unique elements to the front
auto last = std::unique(raw.begin(), raw.end());
// Physically remove the duplicates from vector
raw.erase(last, raw.end());
// raw is now {1, 2, 3, 4}
